/**
 * What the two region map renderers share: where a region links to in each
 * section, how it is labelled, and its colour.
 *
 * The region shapes themselves are generated by `mise run build-trip-index`
 * (scripts/trip-report-index/region-map.ts); this file is presentation only.
 */

/** The three sections that use the region taxonomy (ADR-006), by the path their region pages live under. */
export const REGION_MAP_SECTIONS = {
  'trip-reports': '/hiking-scrambling-beta/trip-reports',
  'weather': '/weather-trail-conditions/popular-locations',
  'accommodation': '/accommodation'
} as const

export type RegionMapSection = keyof typeof REGION_MAP_SECTIONS

export const regionPath = (section: RegionMapSection, regionId: string) =>
  `${REGION_MAP_SECTIONS[section]}/${regionId}`

/**
 * Names short enough to sit inside a region on a map a few hundred pixels
 * wide. A region missing here is labelled with its full title, so adding one
 * to the taxonomy cannot leave it unlabelled.
 */
const SHORT_LABELS: Readonly<Record<string, string>> = {
  'kananaskis-canmore': 'Kananaskis',
  'ghost-front-ranges': 'Ghost',
  'david-thompson': 'David Thompson',
  'banff': 'Banff',
  'assiniboine': 'Assiniboine',
  'yoho': 'Yoho',
  'kootenay': 'Kootenay',
  'icefields-parkway': 'Icefields Pkwy',
  'jasper-robson': 'Jasper · Robson',
  'crowsnest-castle': 'Crowsnest',
  'waterton': 'Waterton',
  'glacier-montana': 'Glacier MT',
  'bc-rockies-purcells': 'BC Rockies',
  'rogers-pass-selkirks': 'Rogers Pass',
  'sea-to-sky': 'Sea to Sky',
  'fraser-valley': 'Fraser Valley',
  'okanagan': 'Okanagan',
  'shuswap-monashees': 'Shuswap',
  'west-kootenay': 'West Kootenay',
  'vancouver-island': 'Vancouver Island'
}

export const regionLabel = (regionId: string, title: string) => SHORT_LABELS[regionId] ?? title

/**
 * Hues by region order, picked so neighbours on the map differ rather than so
 * a region group shares a family — twenty regions are too many for families to
 * stay distinguishable. Alternate regions are drawn darker for the same reason.
 */
const HUES = [150, 25, 48, 195, 265, 215, 300, 175, 235, 355, 15, 35, 280, 320, 95, 205, 60, 330, 120, 5]

export const regionHue = (index: number) => HUES[index % HUES.length]!

/** 1 for the regions drawn darker. */
export const regionShade = (index: number) => index % 2

/**
 * As a literal colour, for MapLibre's paint properties. The SVG renderer takes
 * hue and shade instead and resolves lightness in CSS, so its prerendered
 * markup does not depend on the colour mode.
 */
export function regionColor(index: number, dark: boolean): string {
  const lightness = (dark ? 48 : 52) - regionShade(index) * 10
  return `hsl(${regionHue(index)} 55% ${lightness}%)`
}
